    /** Re-observes a signal whose mirror diverged from the core, to receive a full value. */
    private fun resync(signalId: UInt) {
        core.observe(handle, signalId, false)
        core.observe(handle, signalId, true)
    }

    companion object {
        /**
         * A store with every counter at zero and [`ROWS`] rows numbered from 1.
         * @throws UndraCallError if the core panics, refuses or cancels the call, or cannot be reached.
         */
        fun create(ctx: UndraCore = UndraPlaygroundA.core): Bench {
            val handle = ctx.constructObject(UndraIds.Objects.Bench.TYPE_ID, UndraIds.Objects.Bench.NEW, ByteArray(0))
            return Bench(ctx, handle)
        }
    }
}

/** A list of [`LIST_LEN`] items with operations that change one item at a time. */
class BigList private constructor(core: UndraCore, handle: Long) : UndraStore(core, handle) {
    private val _items: MutableStateFlow<List<Item>> = signal(emptyList())
    val items: StateFlow<List<Item>> = _items.asStateFlow()
    private val _count: MutableStateFlow<UInt> = signal(0u)
    /** Computed by the core; read-only. */
    val count: StateFlow<UInt> = _count.asStateFlow()

    init {
        observeAll()
    }

    /**
     * A list of [`LIST_LEN`] items numbered from 1.
     * @throws UndraCallError if the core panics, refuses or cancels the call, or cannot be reached.
     */
    constructor(ctx: UndraCore = UndraPlaygroundA.core) : this(
        ctx,
        ctx.constructObject(UndraIds.Objects.BigList.TYPE_ID, UndraIds.Objects.BigList.NEW, ByteArray(0)),
    )

    /**
     * Inserts a new row with `label` so that it ends at `index` (`index == len` appends), and
     * returns its identity. One keyed `Insert`.
     * @throws ListError
     * @throws UndraCallError if the core panics, refuses or cancels the call, or cannot be reached.
     */
    fun insertAt(index: UInt, label: String): UInt {
        val w = UndraWriter()
        w.writeU32(index)
        w.writeStr(label)
        try {
            val body = this.core.callSync(
                CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.BigList.INSERT_AT),
                UndraIds.Objects.BigList.INSERT_AT,
                w.toByteArray(),
            )
            return Codecs.u32.decodeAll(body)
        } catch (e: Exception) {
            throw UndraCallError.mapped(e, ListError)
        }
    }

    /**
     * Moves the row at `from` so that it ends at `to`. One keyed `Move`.
     * @throws ListError
     * @throws UndraCallError if the core panics, refuses or cancels the call, or cannot be reached.
     */
    fun moveItem(from: UInt, to: UInt) {
        val w = UndraWriter()
        w.writeU32(from)
        w.writeU32(to)
        try {
            this.core.callSync(
                CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.BigList.MOVE_ITEM),
                UndraIds.Objects.BigList.MOVE_ITEM,
                w.toByteArray(),
            )
        } catch (e: Exception) {
            throw UndraCallError.mapped(e, ListError)
        }
    }

    /**
     * Removes the row at `index`. One keyed `Remove`.
     * @throws ListError
     * @throws UndraCallError if the core panics, refuses or cancels the call, or cannot be reached.
     */
    fun removeAt(index: UInt) {
        val w = UndraWriter()
        w.writeU32(index)
        try {
            this.core.callSync(
                CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.BigList.REMOVE_AT),
                UndraIds.Objects.BigList.REMOVE_AT,
                w.toByteArray(),
            )
        } catch (e: Exception) {
            throw UndraCallError.mapped(e, ListError)
        }
    }

    /**
     * Replaces the list with a fresh one of [`LIST_LEN`] items. The platform receives the keyed
     * patch that turns the old list into the new one (a full value if they have little in
     * common).
     * A failure is logged and passed to `LoadOptions.onError`; the method does not throw.
     */
    fun reset() {
        try {
            this.core.callSync(
                CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.BigList.RESET),
                UndraIds.Objects.BigList.RESET,
                ByteArray(0),
            )
        } catch (e: Exception) {
            this.core.report(e, "BigList.reset")
        }
    }

    /**
     * Changes the label of the row at `index` and bumps its version. One keyed `Update`.
     * @throws ListError
     * @throws UndraCallError if the core panics, refuses or cancels the call, or cannot be reached.
     */
    fun updateAt(index: UInt, label: String) {
        val w = UndraWriter()
        w.writeU32(index)
        w.writeStr(label)
        try {
            this.core.callSync(
                CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.BigList.UPDATE_AT),
                UndraIds.Objects.BigList.UPDATE_AT,
                w.toByteArray(),
            )
        } catch (e: Exception) {
            throw UndraCallError.mapped(e, ListError)
        }
    }

    override fun apply(signalId: UInt, op: ChangeOp, reader: UndraReader) {
        try {
            when (signalId) {
                0u -> {
                    if (op == ChangeOp.FULL) {
                        val value = codecVecItem.decode(reader)
                        reader.finish()
                        _items.value = value
                    } else if (op == ChangeOp.PATCH) {
                        val ops = KeyedPatch.decodePatch(reader, Item)
                        reader.finish()
                        try {
                            _items.value = KeyedPatch.applyPatch(_items.value, ops)
                        } catch (e: WireException.PatchOutOfBounds) {
                            resync(0u)
                        }
                    }
                }
                1u -> {
                    if (op == ChangeOp.FULL) {
                        val value = Codecs.u32.decode(reader)
                        reader.finish()
                        _count.value = value
                    }
                }
                else -> Unit
            }
        } catch (e: Exception) {
            core.report(e, "BigList.apply(signal: $signalId)")
        }
    }

    /** Re-observes a signal whose mirror diverged from the core, to receive a full value. */
    private fun resync(signalId: UInt) {
        core.observe(handle, signalId, false)
        core.observe(handle, signalId, true)
    }

    companion object {
        /**
         * A list of [`LIST_LEN`] items numbered from 1.
         * @throws UndraCallError if the core panics, refuses or cancels the call, or cannot be reached.
         */
        fun create(ctx: UndraCore = UndraPlaygroundA.core): BigList {
            val handle = ctx.constructObject(UndraIds.Objects.BigList.TYPE_ID, UndraIds.Objects.BigList.NEW, ByteArray(0))
            return BigList(ctx, handle)
        }
    }
}

/** A counter with a change tally and a computed parity. */
class Counter private constructor(core: UndraCore, handle: Long) : UndraStore(core, handle) {
    private val _count: MutableStateFlow<Int> = signal(0)
    val count: StateFlow<Int> = _count.asStateFlow()
    private val _changes: MutableStateFlow<UInt> = signal(0u)
    val changes: StateFlow<UInt> = _changes.asStateFlow()
    private val _parity: MutableStateFlow<Parity> = signal(Parity.EVEN)
    /** Computed by the core; read-only. */
    val parity: StateFlow<Parity> = _parity.asStateFlow()

    init {
        observeAll()
    }

    /**
     * A counter at zero with no changes made.
     * @throws UndraCallError if the core panics, refuses or cancels the call, or cannot be reached.
     */
    constructor(ctx: UndraCore = UndraPlaygroundA.core) : this(
        ctx,
        ctx.constructObject(UndraIds.Objects.Counter.TYPE_ID, UndraIds.Objects.Counter.NEW, ByteArray(0)),
    )

    /**
     * Adds `amount` (which may be negative) and counts the change: one transaction, so one
     * change-set for `count`, `changes` and `parity` together. The count saturates instead of
     * overflowing.
     * A failure is logged and passed to `LoadOptions.onError`; the method does not throw.
     */
    fun add(amount: Int) {
        try {
            val w = UndraWriter()
            w.writeI32(amount)
            this.core.callSync(
                CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.Counter.ADD),
                UndraIds.Objects.Counter.ADD,
                w.toByteArray(),
            )
        } catch (e: Exception) {
            this.core.report(e, "Counter.add")
        }
    }

    /**
     * Subtracts one.
     * A failure is logged and passed to `LoadOptions.onError`; the method does not throw.
     */
    fun decrement() {
        try {
            this.core.callSync(
                CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.Counter.DECREMENT),
                UndraIds.Objects.Counter.DECREMENT,
                ByteArray(0),
            )
        } catch (e: Exception) {
            this.core.report(e, "Counter.decrement")
        }
    }

    /**
     * Adds one.
     * A failure is logged and passed to `LoadOptions.onError`; the method does not throw.
     */
    fun increment() {
        try {
            this.core.callSync(
                CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.Counter.INCREMENT),
                UndraIds.Objects.Counter.INCREMENT,
                ByteArray(0),
            )
        } catch (e: Exception) {
            this.core.report(e, "Counter.increment")
        }
    }

    /**
     * Sets the count back to zero and forgets the changes, in one transaction.
     * A failure is logged and passed to `LoadOptions.onError`; the method does not throw.
     */
    fun reset() {
        try {
            this.core.callSync(
                CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.Counter.RESET),
                UndraIds.Objects.Counter.RESET,
                ByteArray(0),
            )
        } catch (e: Exception) {
            this.core.report(e, "Counter.reset")
        }
    }

    override fun apply(signalId: UInt, op: ChangeOp, reader: UndraReader) {
        try {
            when (signalId) {
                0u -> {
                    if (op == ChangeOp.FULL) {
                        val value = Codecs.i32.decode(reader)
                        reader.finish()
                        _count.value = value
                    }
                }
                1u -> {
                    if (op == ChangeOp.FULL) {
                        val value = Codecs.u32.decode(reader)
                        reader.finish()
                        _changes.value = value
                    }
                }
                2u -> {
                    if (op == ChangeOp.FULL) {
                        val value = Parity.decode(reader)
                        reader.finish()
                        _parity.value = value
                    }
                }
                else -> Unit
            }
        } catch (e: Exception) {
            core.report(e, "Counter.apply(signal: $signalId)")
        }
    }

    companion object {
        /**
         * A counter at zero with no changes made.
         * @throws UndraCallError if the core panics, refuses or cancels the call, or cannot be reached.
         */
        fun create(ctx: UndraCore = UndraPlaygroundA.core): Counter {
            val handle = ctx.constructObject(UndraIds.Objects.Counter.TYPE_ID, UndraIds.Objects.Counter.NEW, ByteArray(0))
            return Counter(ctx, handle)
        }
    }
}

/**
 * The `Connectivity` and `Lifecycle` reports as the core received them: the last of each and how
 * many there were since the core started. Every report moves the signals in one transaction, and
 * every signal is `no_coalesce`: a platform's mirror applies each report, even several that arrive
 * in one frame (or while the app is in the background, where React Native on Android pauses the
 * timers that drain it), so a UI or a check sees `background` even when `active` follows at once.
 */
class Device private constructor(core: UndraCore, handle: Long) : UndraStore(core, handle, noCoalesce = setOf(0u, 1u, 2u, 3u, 4u)) {
    private val _online: MutableStateFlow<Boolean> = signal(false)
    val online: StateFlow<Boolean> = _online.asStateFlow()
    private val _netKind: MutableStateFlow<NetKind> = signal(NetKind.WIFI)
    val netKind: StateFlow<NetKind> = _netKind.asStateFlow()
    private val _appState: MutableStateFlow<AppState> = signal(AppState.ACTIVE)
    val appState: StateFlow<AppState> = _appState.asStateFlow()
    private val _connectivityReports: MutableStateFlow<UInt> = signal(0u)
    val connectivityReports: StateFlow<UInt> = _connectivityReports.asStateFlow()
    private val _lifecycleReports: MutableStateFlow<UInt> = signal(0u)
    val lifecycleReports: StateFlow<UInt> = _lifecycleReports.asStateFlow()

    init {
        observeAll()
    }

    /**
     * The store, showing every report received so far and following the next ones.
     * @throws UndraCallError if the core panics, refuses or cancels the call, or cannot be reached.
     */
    constructor(ctx: UndraCore = UndraPlaygroundA.core) : this(
        ctx,
        ctx.constructObject(UndraIds.Objects.Device.TYPE_ID, UndraIds.Objects.Device.NEW, ByteArray(0)),
    )

    override fun apply(signalId: UInt, op: ChangeOp, reader: UndraReader) {
        try {
            when (signalId) {
                0u -> {
                    if (op == ChangeOp.FULL) {
                        val value = Codecs.bool.decode(reader)
                        reader.finish()
                        _online.value = value
                    }
                }
                1u -> {
                    if (op == ChangeOp.FULL) {
                        val value = NetKind.decode(reader)
                        reader.finish()
                        _netKind.value = value
                    }
                }
                2u -> {
                    if (op == ChangeOp.FULL) {
                        val value = AppState.decode(reader)
                        reader.finish()
                        _appState.value = value
                    }
                }
                3u -> {
                    if (op == ChangeOp.FULL) {
                        val value = Codecs.u32.decode(reader)
                        reader.finish()
                        _connectivityReports.value = value
                    }
                }
                4u -> {
                    if (op == ChangeOp.FULL) {
                        val value = Codecs.u32.decode(reader)
                        reader.finish()
                        _lifecycleReports.value = value
                    }
                }
                else -> Unit
            }
        } catch (e: Exception) {
            core.report(e, "Device.apply(signal: $signalId)")
        }
    }

    companion object {
        /**
         * The store, showing every report received so far and following the next ones.
         * @throws UndraCallError if the core panics, refuses or cancels the call, or cannot be reached.
         */
        fun create(ctx: UndraCore = UndraPlaygroundA.core): Device {
            val handle = ctx.constructObject(UndraIds.Objects.Device.TYPE_ID, UndraIds.Objects.Device.NEW, ByteArray(0))
            return Device(ctx, handle)
        }
    }
}

/** The notes of one database, mirrored: `notes` changes only after the database did. */
class Notes private constructor(core: UndraCore, handle: Long) : UndraStore(core, handle) {
    private val _notes: MutableStateFlow<List<Note>> = signal(emptyList())
    val notes: StateFlow<List<Note>> = _notes.asStateFlow()
    private val _version: MutableStateFlow<UInt> = signal(0u)
    val version: StateFlow<UInt> = _version.asStateFlow()

    init {
        observeAll()
    }

    /**
     * No database open yet: call [`open`](Notes::open).
     * @throws UndraCallError if the core panics, refuses or cancels the call, or cannot be reached.
     */
    constructor(ctx: UndraCore = UndraPlaygroundA.core) : this(
        ctx,
        ctx.constructObject(UndraIds.Objects.Notes.TYPE_ID, UndraIds.Objects.Notes.NEW, ByteArray(0)),
    )

    /**
     * Adds a note at the end.
     * @throws DbError
     * @throws UndraCallError if the core panics, refuses or cancels the call, or cannot be reached.
     * @throws CancellationException if the calling coroutine is cancelled.
     */
    suspend fun add(title: String): Note {
        val w = UndraWriter()
        w.writeStr(title)
        try {
            val body = this.core.call(
                CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.Notes.ADD),
                UndraIds.Objects.Notes.ADD,
                w.toByteArray(),
            )
            return Note.decodeAll(body)
        } catch (e: Exception) {
            throw UndraCallError.mapped(e, DbError)
        }
    }

    /**
     * Adds every title in one transaction: all or none. A `None` title breaks `NOT NULL` and
     * rolls the whole batch back. Returns how many were added.
     * @throws DbError
     * @throws UndraCallError if the core panics, refuses or cancels the call, or cannot be reached.
     * @throws CancellationException if the calling coroutine is cancelled.
     */
    suspend fun addAll(titles: List<String?>): UInt {
        val w = UndraWriter()
        codecVecOptionString.encode(w, titles)
        try {
            val body = this.core.call(
                CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.Notes.ADD_ALL),
                UndraIds.Objects.Notes.ADD_ALL,
                w.toByteArray(),
            )
            return Codecs.u32.decodeAll(body)
        } catch (e: Exception) {
            throw UndraCallError.mapped(e, DbError)
        }
    }

    /**
     * Adds a note with a chosen id (an id in use is `Constraint { kind: Unique }`).
     * @throws DbError
     * @throws UndraCallError if the core panics, refuses or cancels the call, or cannot be reached.
     * @throws CancellationException if the calling coroutine is cancelled.
     */
    suspend fun addWithId(id: Long, title: String): Note {
        val w = UndraWriter()
        w.writeI64(id)
        w.writeStr(title)
        try {
            val body = this.core.call(
                CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.Notes.ADD_WITH_ID),
                UndraIds.Objects.Notes.ADD_WITH_ID,
                w.toByteArray(),
            )
            return Note.decodeAll(body)
        } catch (e: Exception) {
            throw UndraCallError.mapped(e, DbError)
        }
    }

    /**
     * Closes the database; the list keeps what it showed (`close` is every store's own: it
     * releases the handle).
     * @throws DbError
     * @throws UndraCallError if the core panics, refuses or cancels the call, or cannot be reached.
     * @throws CancellationException if the calling coroutine is cancelled.
     */
    suspend fun closeDatabase() {
        try {
            this.core.call(
                CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.Notes.CLOSE_DATABASE),
                UndraIds.Objects.Notes.CLOSE_DATABASE,
                ByteArray(0),
            )
        } catch (e: Exception) {
            throw UndraCallError.mapped(e, DbError)
        }
    }

    /**
     * How many notes the database holds (read from it, not from the mirror).
     * @throws DbError
     * @throws UndraCallError if the core panics, refuses or cancels the call, or cannot be reached.
     * @throws CancellationException if the calling coroutine is cancelled.
     */
    suspend fun count(): UInt {
        try {
            val body = this.core.call(
                CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.Notes.COUNT),
                UndraIds.Objects.Notes.COUNT,
                ByteArray(0),
            )
            return Codecs.u32.decodeAll(body)
        } catch (e: Exception) {
            throw UndraCallError.mapped(e, DbError)
        }
    }

    /**
     * Opens (creating it if needed) database `name`, migrates it and loads every note.
     * Returns its version.
     * @throws DbError
     * @throws UndraCallError if the core panics, refuses or cancels the call, or cannot be reached.
     * @throws CancellationException if the calling coroutine is cancelled.
     */
    suspend fun open(name: String): UInt {
        val w = UndraWriter()
        w.writeStr(name)
        try {
            val body = this.core.call(
                CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.Notes.OPEN),
                UndraIds.Objects.Notes.OPEN,
                w.toByteArray(),
            )
            return Codecs.u32.decodeAll(body)
        } catch (e: Exception) {
            throw UndraCallError.mapped(e, DbError)
        }
    }

    /**
     * Removes note `id`.
     * @throws DbError
     * @throws UndraCallError if the core panics, refuses or cancels the call, or cannot be reached.
     * @throws CancellationException if the calling coroutine is cancelled.
     */
    suspend fun remove(id: Long) {
        val w = UndraWriter()
        w.writeI64(id)
        try {
            this.core.call(
                CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.Notes.REMOVE),
                UndraIds.Objects.Notes.REMOVE,
                w.toByteArray(),
            )
        } catch (e: Exception) {
            throw UndraCallError.mapped(e, DbError)
        }
    }

    /**
     * Ticks or unticks note `id`.
     * @throws DbError
     * @throws UndraCallError if the core panics, refuses or cancels the call, or cannot be reached.
     * @throws CancellationException if the calling coroutine is cancelled.
     */
    suspend fun toggle(id: Long) {
        val w = UndraWriter()
        w.writeI64(id)
        try {
            this.core.call(
                CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.Notes.TOGGLE),
                UndraIds.Objects.Notes.TOGGLE,
                w.toByteArray(),
            )
        } catch (e: Exception) {
            throw UndraCallError.mapped(e, DbError)
        }
    }

    override fun apply(signalId: UInt, op: ChangeOp, reader: UndraReader) {
        try {
            when (signalId) {
                0u -> {
                    if (op == ChangeOp.FULL) {
                        val value = codecVecNote.decode(reader)
                        reader.finish()
                        _notes.value = value
                    } else if (op == ChangeOp.PATCH) {
                        val ops = KeyedPatch.decodePatch(reader, Note)
                        reader.finish()
                        try {
                            _notes.value = KeyedPatch.applyPatch(_notes.value, ops)
                        } catch (e: WireException.PatchOutOfBounds) {
                            resync(0u)
                        }
                    }
                }
                1u -> {
                    if (op == ChangeOp.FULL) {
                        val value = Codecs.u32.decode(reader)
                        reader.finish()
                        _version.value = value
                    }
                }
                else -> Unit
            }
        } catch (e: Exception) {
            core.report(e, "Notes.apply(signal: $signalId)")
        }
    }

    /** Re-observes a signal whose mirror diverged from the core, to receive a full value. */
    private fun resync(signalId: UInt) {
        core.observe(handle, signalId, false)
        core.observe(handle, signalId, true)
    }

    companion object {
        /**
         * No database open yet: call [`open`](Notes::open).
         * @throws UndraCallError if the core panics, refuses or cancels the call, or cannot be reached.
         */
        fun create(ctx: UndraCore = UndraPlaygroundA.core): Notes {
            val handle = ctx.constructObject(UndraIds.Objects.Notes.TYPE_ID, UndraIds.Objects.Notes.NEW, ByteArray(0))
            return Notes(ctx, handle)
        }
    }
}

/**
 * A store that commits many transactions, for the coalesced-delivery scenarios and the
 * playground's stress screen.
 */
class Stress private constructor(core: UndraCore, handle: Long) : UndraStore(core, handle, noCoalesce = setOf(1u)) {
    private val _value: MutableStateFlow<ULong> = signal(0uL)
    val value: StateFlow<ULong> = _value.asStateFlow()
    private val _progress: MutableStateFlow<UInt> = signal(0u)
    val progress: StateFlow<UInt> = _progress.asStateFlow()
    private val _generated: MutableStateFlow<ULong> = signal(0uL)
    val generated: StateFlow<ULong> = _generated.asStateFlow()
    private val _running: MutableStateFlow<Boolean> = signal(false)
    val running: StateFlow<Boolean> = _running.asStateFlow()

    init {
        observeAll()
    }

    /**
     * A store with every signal at its start: zeros, and no generator running.
     * @throws UndraCallError if the core panics, refuses or cancels the call, or cannot be reached.
     */
    constructor(ctx: UndraCore = UndraPlaygroundA.core) : this(
        ctx,
        ctx.constructObject(UndraIds.Objects.Stress.TYPE_ID, UndraIds.Objects.Stress.NEW, ByteArray(0)),
    )

    /**
     * Commits `transactions` transactions now, each one write of the signal `mode` names: one
     * change-set per transaction, the way data that arrives in the core on its own does.
     * A failure is logged and passed to `LoadOptions.onError`; the method does not throw.
     */
    fun burst(mode: StressMode, transactions: UInt) {
        try {
            val w = UndraWriter()
            StressMode.encode(w, mode)
            w.writeU32(transactions)
            this.core.callSync(
                CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.Stress.BURST),
                UndraIds.Objects.Stress.BURST,
                w.toByteArray(),
            )
        } catch (e: Exception) {
            this.core.report(e, "Stress.burst")
        }
    }

    /**
     * Starts generating updates of the signal the mode names, at the given number a second,
     * each its own transaction, until `stop`. Called while a generator runs, it retunes that
     * generator (new mode, new rate) instead of starting a second one. Fails, starting
     * nothing, when the rate is zero or above 1,000,000.
     * @throws StressError
     * @throws UndraCallError if the core panics, refuses or cancels the call, or cannot be reached.
     */
    fun start(mode: StressMode, perSecond: UInt) {
        val w = UndraWriter()
        StressMode.encode(w, mode)
        w.writeU32(perSecond)
        try {
            this.core.callSync(
                CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.Stress.START),
                UndraIds.Objects.Stress.START,
                w.toByteArray(),
            )
        } catch (e: Exception) {
            throw UndraCallError.mapped(e, StressError)
        }
    }

    /**
     * Stops the generator: no update is committed after this returns. `generated` keeps its
     * count. Does nothing when no generator runs.
     * A failure is logged and passed to `LoadOptions.onError`; the method does not throw.
     */
    fun stop() {
        try {
            this.core.callSync(
                CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.Stress.STOP),
                UndraIds.Objects.Stress.STOP,
                ByteArray(0),
            )
        } catch (e: Exception) {
            this.core.report(e, "Stress.stop")
        }
    }

    override fun apply(signalId: UInt, op: ChangeOp, reader: UndraReader) {
        try {
            when (signalId) {
                0u -> {
                    if (op == ChangeOp.FULL) {
                        val value = Codecs.u64.decode(reader)
                        reader.finish()
                        _value.value = value
                    }
                }
                1u -> {
                    if (op == ChangeOp.FULL) {
                        val value = Codecs.u32.decode(reader)
                        reader.finish()
                        _progress.value = value
                    }
                }
                2u -> {
                    if (op == ChangeOp.FULL) {
                        val value = Codecs.u64.decode(reader)
                        reader.finish()
                        _generated.value = value
                    }
                }
                3u -> {
                    if (op == ChangeOp.FULL) {
                        val value = Codecs.bool.decode(reader)
                        reader.finish()
                        _running.value = value
                    }
                }
                else -> Unit
            }
        } catch (e: Exception) {
            core.report(e, "Stress.apply(signal: $signalId)")
        }
    }

    companion object {
        /**
         * A store with every signal at its start: zeros, and no generator running.
         * @throws UndraCallError if the core panics, refuses or cancels the call, or cannot be reached.
         */
        fun create(ctx: UndraCore = UndraPlaygroundA.core): Stress {
            val handle = ctx.constructObject(UndraIds.Objects.Stress.TYPE_ID, UndraIds.Objects.Stress.NEW, ByteArray(0))
            return Stress(ctx, handle)
        }
    }
}

/** The to-do list: what the UI observes (`todos`, `filter`, `visible`, `remaining`) and calls. */
class Todos private constructor(core: UndraCore, handle: Long) : UndraStore(core, handle) {
    private val _todos: MutableStateFlow<List<Todo>> = signal(emptyList())
    val todos: StateFlow<List<Todo>> = _todos.asStateFlow()
    private val _filter: MutableStateFlow<Filter> = signal(Filter.ALL)
    val filter: StateFlow<Filter> = _filter.asStateFlow()
    private val _visible: MutableStateFlow<List<Todo>> = signal(emptyList())
    /** Derived by the core from another list; read-only. Changes arrive as keyed patches. */
    val visible: StateFlow<List<Todo>> = _visible.asStateFlow()
    private val _remaining: MutableStateFlow<UInt> = signal(0u)
    /** Computed by the core; read-only. */
    val remaining: StateFlow<UInt> = _remaining.asStateFlow()

    init {
        observeAll()
    }

    /**
     * An empty list showing every item.
     * @throws UndraCallError if the core panics, refuses or cancels the call, or cannot be reached.
     */
    constructor(ctx: UndraCore = UndraPlaygroundA.core) : this(
        ctx,
        ctx.constructObject(UndraIds.Objects.Todos.TYPE_ID, UndraIds.Objects.Todos.NEW, ByteArray(0)),
    )

    /**
     * Adds an item at the end of the list.
     * @throws TodoError
     * @throws UndraCallError if the core panics, refuses or cancels the call, or cannot be reached.
     * @throws CancellationException if the calling coroutine is cancelled.
     */
    suspend fun add(title: String): Todo {
        val w = UndraWriter()
        w.writeStr(title)
        try {
            val body = this.core.call(
                CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.Todos.ADD),
                UndraIds.Objects.Todos.ADD,
                w.toByteArray(),
            )
            return Todo.decodeAll(body)
        } catch (e: Exception) {
            throw UndraCallError.mapped(e, TodoError)
        }
    }

    /**
     * Removes every finished item.
     * A failure is logged and passed to `LoadOptions.onError`; the method does not throw.
     */
    fun clearDone() {
        try {
            this.core.callSync(
                CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.Todos.CLEAR_DONE),
                UndraIds.Objects.Todos.CLEAR_DONE,
                ByteArray(0),
            )
        } catch (e: Exception) {
            this.core.report(e, "Todos.clearDone")
        }
    }

    /**
     * Appends `count` items titled `Item 1`, `Item 2`, .. with every fourth one finished, in one
     * transaction (a demo and test helper: the big-list screen of the docs, contract scenario S19).
     * A bulk load is a raw write, so `todos` and `visible` are sent as full values this once; the
     * writes after it are patches again.
     * A failure is logged and passed to `LoadOptions.onError`; the method does not throw.
     */
    fun fill(count: UInt) {
        try {
            val w = UndraWriter()
            w.writeU32(count)
            this.core.callSync(
                CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.Todos.FILL),
                UndraIds.Objects.Todos.FILL,
                w.toByteArray(),
            )
        } catch (e: Exception) {
            this.core.report(e, "Todos.fill")
        }
    }

    /**
     * Removes the item with `id`; unknown ids are ignored.
     * A failure is logged and passed to `LoadOptions.onError`; the method does not throw.
     */
    fun remove(id: UUID) {
        try {
            val w = UndraWriter()
            Codecs.uuid.encode(w, id)
            this.core.callSync(
                CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.Todos.REMOVE),
                UndraIds.Objects.Todos.REMOVE,
                w.toByteArray(),
            )
        } catch (e: Exception) {
            this.core.report(e, "Todos.remove")
        }
    }

    /**
     * Chooses which items `visible` holds.
     * A failure is logged and passed to `LoadOptions.onError`; the method does not throw.
     */
    fun setFilter(filter: Filter) {
        try {
            val w = UndraWriter()
            Filter.encode(w, filter)
            this.core.callSync(
                CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.Todos.SET_FILTER),
                UndraIds.Objects.Todos.SET_FILTER,
                w.toByteArray(),
            )
        } catch (e: Exception) {
            this.core.report(e, "Todos.setFilter")
        }
    }

    /**
     * Flips the `done` flag of the item with `id`; unknown ids are ignored.
     * A failure is logged and passed to `LoadOptions.onError`; the method does not throw.
     */
    fun toggle(id: UUID) {
        try {
            val w = UndraWriter()
            Codecs.uuid.encode(w, id)
            this.core.callSync(
                CallTarget.ObjectMethod(Handle(this.handle), UndraIds.Objects.Todos.TOGGLE),
                UndraIds.Objects.Todos.TOGGLE,
                w.toByteArray(),
            )
        } catch (e: Exception) {
            this.core.report(e, "Todos.toggle")
        }
    }

    override fun apply(signalId: UInt, op: ChangeOp, reader: UndraReader) {
        try {
            when (signalId) {
                0u -> {
                    if (op == ChangeOp.FULL) {
                        val value = codecVecTodo.decode(reader)
                        reader.finish()
                        _todos.value = value
                    } else if (op == ChangeOp.PATCH) {
                        val ops = KeyedPatch.decodePatch(reader, Todo)
                        reader.finish()
                        try {
                            _todos.value = KeyedPatch.applyPatch(_todos.value, ops)
                        } catch (e: WireException.PatchOutOfBounds) {
                            resync(0u)
                        }
                    }
                }
                1u -> {
                    if (op == ChangeOp.FULL) {
                        val value = Filter.decode(reader)
                        reader.finish()
                        _filter.value = value
                    }
                }
                2u -> {
                    if (op == ChangeOp.FULL) {
                        val value = codecVecTodo.decode(reader)
                        reader.finish()
                        _visible.value = value
                    } else if (op == ChangeOp.PATCH) {
                        val ops = KeyedPatch.decodePatch(reader, Todo)
                        reader.finish()
                        try {
                            _visible.value = KeyedPatch.applyPatch(_visible.value, ops)
                        } catch (e: WireException.PatchOutOfBounds) {
                            resync(2u)
                        }
                    }
                }
                3u -> {
                    if (op == ChangeOp.FULL) {
                        val value = Codecs.u32.decode(reader)
                        reader.finish()
                        _remaining.value = value
                    }
                }
                else -> Unit
            }
        } catch (e: Exception) {
            core.report(e, "Todos.apply(signal: $signalId)")
        }
    }

    /** Re-observes a signal whose mirror diverged from the core, to receive a full value. */
    private fun resync(signalId: UInt) {
        core.observe(handle, signalId, false)
        core.observe(handle, signalId, true)
    }

    companion object {
        /**
         * An empty list showing every item.
         * @throws UndraCallError if the core panics, refuses or cancels the call, or cannot be reached.
         */
        fun create(ctx: UndraCore = UndraPlaygroundA.core): Todos {
            val handle = ctx.constructObject(UndraIds.Objects.Todos.TYPE_ID, UndraIds.Objects.Todos.NEW, ByteArray(0))
            return Todos(ctx, handle)
        }
    }
}

private val codecVecItem = Codecs.vec(Item)
private val codecOptionString = Codecs.option(Codecs.string)
private val codecVecOptionString = Codecs.vec(codecOptionString)
private val codecVecNote = Codecs.vec(Note)
private val codecVecTodo = Codecs.vec(Todo)
